206:    public StaffLookupItem getStaff(int staffCode) {
207:        String sql = "SELECT S.職員番号 AS STAFF_NO, S.漢字氏名 AS STAFF_NAME, "
208:                + "S.カナ氏名 AS STAFF_KANA_NAME, S.所属店番 AS BRANCH_NO, "
209:                + "S.役職コード AS ROLE_CODE FROM " + STAFF_TABLE
210:                + " S WHERE S.職員番号 = ?";
211:        Map<Integer, String> branchNames = loadBranchNames();
212:        Connection connection = null;
213:        PreparedStatement statement = null;
214:        ResultSet results = null;
215:        try {
216:            connection = NenkinDataSource.openStaffConnection();
217:            statement = connection.prepareStatement(sql);
218:            statement.setInt(1, staffCode);
219:            results = statement.executeQuery();
220:            return results.next() ? readStaff(results, branchNames) : null;
221:        } catch (SQLException e) {
222:            throw failure("職員の取得", e);
223:        } finally {
224:            close(results);
225:            close(statement);
226:            close(connection);
227:        }
228:    }
