289:    private Map<Integer, String> loadBranchNames() {
290:        Map<Integer, String> branchNames = new HashMap<Integer, String>();
291:        String sql = "SELECT 店舗ｺｰﾄﾞ AS BRANCH_NO, 店名 AS BRANCH_NAME FROM "
292:                + BRANCH_TABLE;
293:        Connection connection = null;
294:        PreparedStatement statement = null;
295:        ResultSet results = null;
296:        try {
297:            connection = NenkinDataSource.openConnection();
298:            statement = connection.prepareStatement(sql);
299:            results = statement.executeQuery();
300:            while (results.next()) {
301:                branchNames.put(Integer.valueOf(results.getInt("BRANCH_NO")),
302:                        results.getString("BRANCH_NAME"));
303:            }
304:            return branchNames;
305:        } catch (SQLException e) {
306:            throw failure("店舗名の取得", e);
307:        } finally {
308:            close(results);
309:            close(statement);
310:            close(connection);
311:        }
312:    }
