314:    private static StaffLookupItem readStaff(ResultSet results,
315:            Map<Integer, String> branchNames) throws SQLException {
316:        int branchNo = results.getInt("BRANCH_NO");
317:        String branchName = branchNames.get(Integer.valueOf(branchNo));
318:        return new StaffLookupItem(results.getInt("STAFF_NO"),
319:                results.getString("STAFF_NAME"), results.getString("STAFF_KANA_NAME"),
320:                branchNo, branchName == null ? "" : branchName,
321:                results.getString("ROLE_CODE"));
322:    }
