17:            + "(\u5143|[0-9]{1,3})[\\./\\-\u5e74]\\s*([0-9]{1,2})[\\./\\-\u6708]\\s*"
18:            + "([0-9]{1,2})\u65e5?$", Pattern.CASE_INSENSITIVE);
19:    private static final Pattern GREGORIAN_DATE = Pattern.compile(
20:            "^([0-9]{4})[\\./\\-]([0-9]{1,2})[\\./\\-]([0-9]{1,2})$");
21:    private static final Pattern COMPACT_DATE = Pattern.compile("^([0-9]{4})([0-9]{2})([0-9]{2})$");
22:
