34:    /** yyyy-MM-dd、yyyy/MM/dd、yyyyMMdd、和暦を yyyy-MM-dd に正規化する。 */
35:    public static String toIsoDate(String value) {
36:        String input = normalizeInput(value);
37:        if (input.length() == 0) {
38:            return "";
39:        }
40:
41:        Matcher eraMatcher = ERA_DATE.matcher(input);
42:        if (eraMatcher.matches()) {
43:            Era era = findEra(eraMatcher.group(1));
44:            int eraYear = "元".equals(eraMatcher.group(2))
45:                    ? 1 : Integer.parseInt(eraMatcher.group(2));
46:            if (eraYear <= 0) {
47:                throw invalid(value);
48:            }
49:            int year = era.baseYear + eraYear - 1;
50:            String iso = formatIso(year, Integer.parseInt(eraMatcher.group(3)),
51:                    Integer.parseInt(eraMatcher.group(4)), value);
52:            Date date = parseIso(iso, value);
53:            if (date.before(era.start) || (era.end != null && date.after(era.end))) {
54:                throw invalid(value);
55:            }
56:            return iso;
57:        }
58:
59:        Matcher western = GREGORIAN_DATE.matcher(input);
60:        if (western.matches()) {
61:            return formatIso(Integer.parseInt(western.group(1)),
62:                    Integer.parseInt(western.group(2)), Integer.parseInt(western.group(3)), value);
63:        }
64:
65:        Matcher compact = COMPACT_DATE.matcher(input);
66:        if (compact.matches()) {
67:            return formatIso(Integer.parseInt(compact.group(1)),
68:                    Integer.parseInt(compact.group(2)), Integer.parseInt(compact.group(3)), value);
69:        }
70:
71:        throw invalid(value);
180:        }
181:    }
