183:    private static String twoDigits(int value) {
184:        return value < 10 ? "0" + value : Integer.toString(value);
185:    }
186:
187:    private static String twoOrMoreDigits(int value) {
188:        return value < 10 ? "0" + value : Integer.toString(value);
189:    }
190:
191:    private static String fourDigits(int value) {
192:        String result = Integer.toString(value);
193:        while (result.length() < 4) {
194:            result = "0" + result;
195:        }
196:        return result;
197:    }
198:
199:    private static IllegalArgumentException invalid(String value) {
200:        return new IllegalArgumentException("日付の形式または実在性が不正です: " + value);
201:    }
